<script setup>
import { ref,onMounted,watch } from 'vue'
import axios from 'axios'
import { useSchoolStore } from '../stores/school'
import Notice from '../components/Notice.vue'
const store=useSchoolStore(),studentId=ref(''),courseId=ref(''),rosterCourse=ref(''),roster=ref([]),message=ref(''),error=ref(false),busy=ref(false),loadingRoster=ref(false)
function show(t,e=false){message.value=t;error.value=e}
onMounted(async()=>{try{await store.refresh()}catch(e){show('Cannot load students or courses',true)}})
async function enroll(){if(!studentId.value||!courseId.value)return show('Select a student and a course',true);busy.value=true;try{await axios.post('/api/enrollments',{studentId:studentId.value,courseId:courseId.value});show('Enrollment added successfully');if(rosterCourse.value===courseId.value)await loadRoster()}catch(e){show(e.response?.data?.error||'Could not enroll student',true)}finally{busy.value=false}}
async function loadRoster(){roster.value=[];if(!rosterCourse.value)return;loadingRoster.value=true;try{const res=await axios.get(`/api/courses/${encodeURIComponent(rosterCourse.value)}/students`);roster.value=res.data}catch(e){show(e.response?.data?.error||'Cannot load roster',true)}finally{loadingRoster.value=false}}
watch(rosterCourse,loadRoster)
</script>
<template><h2>Enrollments</h2><Notice :message="message" :error="error" /><section class="panel"><h3>Enroll a Student</h3><form class="form-grid" @submit.prevent="enroll"><label>Student<select v-model="studentId" required><option value="">Select a student</option><option v-for="s in store.students" :key="s.id" :value="s.id">{{s.name}} ({{s.id}})</option></select></label><label>Course<select v-model="courseId" required><option value="">Select a course</option><option v-for="c in store.courses" :key="c.id" :value="c.id">{{c.id}} — {{c.title}}</option></select></label><button :disabled="busy||!store.students.length||!store.courses.length">Enroll Student</button></form><p v-if="!store.students.length||!store.courses.length" class="muted">Add at least one student and one course first.</p></section><section class="panel"><h3>Students in a Course</h3><label>Select Course<select v-model="rosterCourse"><option value="">Choose a course</option><option v-for="c in store.courses" :key="c.id" :value="c.id">{{c.id}} — {{c.title}}</option></select></label><p v-if="loadingRoster">Loading roster...</p><p v-else-if="rosterCourse&&!roster.length">No students enrolled in this course.</p><div v-else-if="roster.length" class="table-wrap"><table><thead><tr><th>Student ID</th><th>Name</th><th>Phone</th><th>ZIP</th></tr></thead><tbody><tr v-for="s in roster" :key="s.id"><td>{{s.id}}</td><td>{{s.name}}</td><td>{{s.phone}}</td><td>{{s.zip}}</td></tr></tbody></table></div></section></template>
